def rotations(v):
    return [(list(p), [Decimal(str(v[i])) for i in p]) for p in itertools.permutations(range(3))]
def single_fits(oriented, container):
    return all(oriented[i] <= Decimal(str(container[i])) for i in range(3))
def two_boxes_fit(a,b,container):
    if not single_fits(a,container) or not single_fits(b,container): return False
    return any(a[k]+b[k] <= Decimal(str(container[k])) for k in range(3))
# For two closed axis-aligned boxes, disjoint interiors require separation on at least one coordinate axis.
# With both individually contained, a_k+b_k <= C_k is necessary and sufficient for such separation.
